/**
 * What the app supports: one source for the in-app "What is supported" page
 * and docs/user/supported.md (generated by scripts/gen-supported-doc.ts; a
 * test fails when the doc drifts from this file).
 */
import { TEMPLATES } from '@/lib/pointing/templates'
import { CATALOGUE } from '@/lib/layout/catalogue'

export type Level = 'yes' | 'partial' | 'no'

export interface SupportRow {
  feature: string
  level: Level
  note: string
}

export interface SupportGroup {
  title: string
  rows: SupportRow[]
}

export function supportMatrix(): SupportGroup[] {
  return [
    {
      title: 'Firmware',
      rows: [
        { feature: 'ZMK keymap (.keymap)', level: 'yes', note: 'Layers, bindings, combos, layer add/rename/delete. Saves change only the edited lines; comments are kept.' },
        { feature: 'ZMK behaviors', level: 'yes', note: 'Hold-tap, mod-morph, tap-dance, macro, sticky-key and any other `zmk,behavior-*` node: edit properties, add, remove.' },
        { feature: 'ZMK #if / #ifdef inside the keymap block', level: 'partial', note: 'The keymap opens read-only so the editor never rewrites what it cannot reproduce.' },
        { feature: 'ZMK single boards and splits', level: 'yes', note: 'Configs that build a shield or a board with the controller built in (Glove80, nice!60, BT60, Planck) are detected; one part or several.' },
        { feature: 'QMK keymap.json and VIA export', level: 'yes', note: 'Key bindings on the physical layout; found anywhere in a qmk_userspace or keymap folder; layout from info.json / keyboard.json or downloaded from QMK; combos from keymap.c when present.' },
        { feature: 'QMK keymap.c key editing', level: 'no', note: 'Make a keymap.json with `qmk c2json` (the app shows the command) or use a VIA export.' },
        { feature: 'VIA / Vial: read the keymap over USB', level: 'yes', note: 'Plugged in reads every layer and saves a backup first.' },
        { feature: 'VIA / Vial: write keys over USB', level: 'partial', note: 'Experimental, not yet tested on a real VIA or Vial keyboard. Build › Write to keyboard backs up, writes only changed keys, reads each back and checks the whole keymap. No lighting, macro or Vial combo writes.' },
      ],
    },
    {
      title: 'Physical layouts',
      rows: [
        { feature: 'ZMK `zmk,physical-layout` (dtsi)', level: 'yes', note: 'Detected from the shield folder.' },
        { feature: 'keymap-editor / QMK info.json, keyboard.json', level: 'yes', note: 'Detected or imported.' },
        { feature: 'keyboard-layout-editor (KLE) JSON', level: 'yes', note: 'Import file in Settings.' },
        { feature: 'Matrix transform grid', level: 'yes', note: 'Fallback when no geometry is available.' },
        { feature: 'Bundled catalogue', level: 'yes', note: `${CATALOGUE.length} layouts from ZMK's shared layouts.` },
        { feature: 'Find my keyboard', level: 'yes', note: 'Bundled ZMK keyboards (single boards and splits) and popular QMK splits work offline; any other QMK keyboard is found by searching QMK\'s online list.' },
        { feature: 'Drawing a layout by hand', level: 'no', note: 'Import a KLE file instead.' },
      ],
    },
    {
      title: 'Pointing devices',
      rows: [
        { feature: 'Tune Azoteq IQS5XX trackpad', level: 'yes', note: 'Speed, scroll, natural scroll, taps, press-and-hold, axis flips, filtering, snipe, scroll layer.' },
        { feature: 'Tune Pixart PMW3610 / PMW3360 trackball', level: 'yes', note: 'Speed, CPI, invert, smart mode, snipe, scroll layer.' },
        { feature: 'Tune Cirque Pinnacle trackpad', level: 'yes', note: 'Speed, sensitivity, invert, snipe, scroll layer.' },
        ...TEMPLATES.map((t): SupportRow => ({
          feature: `Add ${t.name.replace(/ — untested$/, '')}`,
          level: t.tested ? 'yes' : 'partial',
          note: t.tested
            ? `Tested on ${t.tested.controller}, ${t.tested.zmk}. Remove restores the files exactly.`
            : 'Untested template: review every pin in the diff preview before applying.',
        })),
        { feature: 'QMK pointing flags', level: 'yes', note: 'POINTING_DEVICE_ENABLE / DRIVER, rotation, invert, CPI in rules.mk and config.h.' },
      ],
    },
    {
      title: 'Build & flash',
      rows: [
        { feature: 'GitHub Actions firmware builds', level: 'yes', note: 'Requires a separately installed GitHub CLI (`gh`) and your own GitHub login; this is not a self-contained local build tool.' },
        { feature: 'Flash a UF2 to a keyboard or half in bootloader', level: 'yes', note: 'Waits for the drive and copies the file. For QMK, any .uf2 built elsewhere (RP2040 boards).' },
        { feature: 'QMK firmware builds', level: 'no', note: 'The Build tab shows the exact `qmk compile` / `qmk flash` commands and the QMK Configurator route; DFU and other non-UF2 flashing go through QMK Toolbox.' },
        { feature: 'Build the config on screen', level: 'yes', note: 'Build saves, commits and pushes only the keymap and pointing files, waits for that commit\'s GitHub build and downloads it; Flash only offers firmware built from the commit on screen.' },
      ],
    },
    {
      title: 'This Mac',
      rows: [
        { feature: 'Native MacBook remapping', level: 'partial', note: 'Built-in keyboard remaps, combos, layers and homerow mods through the bundled driver and service; no Karabiner-Elements app required. macOS 13+ on Apple silicon, administrator/driver and Input Monitoring approvals required. Live hardware acceptance remains pending.' },
        { feature: 'Karabiner-Elements compatibility export', level: 'yes', note: 'Optional JSON export for an existing Karabiner-Elements setup. Saved rules are preserved; the native flow does not require that app.' },
        { feature: 'Scroll engine for wheel mice', level: 'yes', note: 'Reverse direction and speed. Needs Accessibility permission.' },
        { feature: 'Turn off the built-in keyboard', level: 'yes', note: 'Restored when the app quits normally, or on its next launch after a crash.' },
      ],
    },
    {
      title: 'Platform',
      rows: [
        { feature: 'macOS 13+ (Apple silicon native product)', level: 'yes', note: 'Development previews are not commercial notarized releases. Public distribution requires a Developer ID-signed and notarized complete installer.' },
        { feature: 'Complete-installer updates', level: 'partial', note: 'Native releases open the release page for the complete installer, updating app and keyboard service together. Requires a published release; app-only in-app updates are disabled for native versions.' },
        { feature: 'Windows / Linux / web', level: 'no', note: 'Not in version 1.' },
      ],
    },
  ]
}

const MARK: Record<Level, string> = { yes: 'Yes', partial: 'Partly', no: 'No' }

export function supportMarkdown(): string {
  const out = ['# What Ultimate Keyboards supports', '', '<!-- generated from src/lib/supported.ts by scripts/gen-supported-doc.ts; do not edit by hand -->', '']
  for (const g of supportMatrix()) {
    out.push(`## ${g.title}`, '', '| Feature | Supported | Notes |', '|---|---|---|')
    for (const r of g.rows) out.push(`| ${r.feature} | ${MARK[r.level]} | ${r.note.replace(/\|/g, '\\|')} |`)
    out.push('')
  }
  return out.join('\n')
}

export const LEVEL_LABEL = MARK
